// Teste de fumaça da base E2E real: confirma que o login real, a sessão em cache e o front
// conversam com o backend de verdade. Pode ser apagado quando houver testes reais de fluxo.

describe('Sessão real (fumaça)', () => {
  beforeEach(() => {
    cy.loginReal('cliente')
  })

  it('cliente autenticado abre /login → é redirecionado para o painel', () => {
    cy.visit('/login')

    cy.location('pathname').should('eq', '/')
    cy.getCookie('access_token').should('exist')
  })
})
